print("Checking if TypeScript and g++ compilers are available...")
import subprocess

def check_compiler(command):
    try:
        subprocess.run(command, stdout=subprocess.PIPE, stderr=subprocess.PIPE, check=True)
        print(f"{command[0]} is available.")
    except subprocess.CalledProcessError:
        print(f"{command[0]} is not available.")

check_compiler(["tsc", "--version"])
check_compiler(["g++", "--version"])
